// Convierte los eventos de Google en una lista corta para que RoboDragón la lea
const eventos = $input.all().map(i => i.json).filter(e => e.start);
if (eventos.length === 0) {
  return [{ json: { texto: 'No hay nada en el calendario para esas fechas.' } }];
}
const lineas = eventos.map(e => {
  const titulo = e.summary || '(sin título)';
  if (e.start.date) {
    return DateTime.fromISO(e.start.date).setLocale('es').toFormat('cccc d') + ', todo el día: ' + titulo;
  }
  const inicio = DateTime.fromISO(e.start.dateTime).setZone('Atlantic/Canary').setLocale('es');
  return inicio.toFormat("cccc d 'a las' HH:mm") + ': ' + titulo;
});
return [{ json: { texto: lineas.join('\n') } }];
